<script setup lang="ts">
import { computed,onMounted,ref } from 'vue'
import { useMediaQuery } from '@vueuse/core'
import { useRoute,useRouter } from 'vue-router'
import { NAlert,NButton,NCard,NDescriptions,NDescriptionsItem,NEmpty,NSpin,NTag,NText } from 'naive-ui'
import type { AiInvestigation } from '@nodeaccess/shared'
import { aiInvestigationService } from '@/services/ai-investigation.service'
const route=useRoute(),router=useRouter(),row=ref<AiInvestigation|null>(null),loading=ref(true),error=ref('')
const id=computed(()=>Number(route.params.id)),open=computed(()=>['OPEN','WAITING_USER'].includes(row.value?.status??'')),fmt=(v:any)=>v?new Date(v).toLocaleString('pt-BR'):'—'
const compact=useMediaQuery('(max-width: 639px)'), descriptionColumns=computed(()=>compact.value?1:3)
const statusLabels:Record<string,string>={OPEN:'Em andamento',WAITING_USER:'Aguardando sua decisão',COMPLETED:'Concluída',ABANDONED:'Encerrada'}
const statusLabel=computed(()=>statusLabels[row.value?.status??'']??row.value?.status)
async function load(){loading.value=true;try{row.value=(await aiInvestigationService.get(id.value)).data}catch{error.value='Não foi possível carregar esta investigação.'}finally{loading.value=false}}
async function abandon(){if(!confirm('Encerrar esta investigação sem relatório final?'))return;row.value=(await aiInvestigationService.abandon(id.value)).data}
onMounted(load)
</script>
<template><div class="p-4 sm:p-6" data-testid="ai-investigation-detail"><NButton text class="mb-3" @click="router.push({name:'admin-ai-investigations'})">Voltar às investigações</NButton><NAlert v-if="error" type="error">{{error}}</NAlert><NSpin :show="loading"><template v-if="row"><div class="mb-5 flex flex-wrap items-start justify-between gap-3"><div><div class="flex flex-wrap items-center gap-2"><h1 class="text-xl font-semibold text-white">Investigação #{{row.id}}</h1><NTag :type="open?'warning':'success'" data-testid="investigation-status">{{statusLabel}}</NTag></div><NText depth="3">{{row.objective}}</NText></div><NButton v-if="open" type="error" tertiary @click="abandon">Encerrar sem relatório</NButton></div><NAlert v-if="open" type="info" class="mb-4" data-testid="investigation-guidance" title="O agente está aguardando sua decisão">As conexões SSH são encerradas após cada execução. Peça ao agente para continuar nesta investigação ou confirme que terminou; somente então ele registrará a conclusão.</NAlert><NCard embedded class="mb-4"><NDescriptions bordered label-placement="top" :column="descriptionColumns"><NDescriptionsItem label="Host">{{row.hostName}} · {{row.hostIp}}</NDescriptionsItem><NDescriptionsItem label="Solicitante">{{row.requestedByName}}</NDescriptionsItem><NDescriptionsItem label="Token MCP">{{row.mcpTokenName??'Sem token persistido'}}</NDescriptionsItem><NDescriptionsItem label="Criada">{{fmt(row.createdAt)}}</NDescriptionsItem><NDescriptionsItem label="Última atividade">{{fmt(row.lastActivityAt)}}</NDescriptionsItem><NDescriptionsItem label="Expira">{{fmt(row.expiresAt)}}</NDescriptionsItem></NDescriptions></NCard><h2 class="mb-3 text-base font-semibold">Execuções e evidências</h2><div v-if="row.actionRuns.length" class="space-y-3" data-testid="investigation-runs"><NCard v-for="run in row.actionRuns" :key="run.id" embedded><div class="flex flex-wrap items-center justify-between gap-2"><div><NText strong>{{run.summary}}</NText><div class="text-xs text-zinc-500">ActionRun #{{run.id}} · {{fmt(run.createdAt)}}</div></div><div class="flex flex-wrap gap-2"><NTag>{{run.status}}</NTag><NButton size="small" secondary @click="router.push({name:'ai-ssh-action-run-detail',params:{runId:run.id}})">Abrir comandos e saídas</NButton></div></div></NCard></div><NEmpty v-else description="O agente ainda não vinculou nenhuma execução."/><h2 class="mb-3 mt-6 text-base font-semibold">Conclusão do agente</h2><div v-if="row.reports.length" class="space-y-3" data-testid="investigation-reports"><NCard v-for="report in row.reports" :key="report.id" embedded><div class="flex flex-wrap justify-between gap-2"><div><NText strong>Relatório complementar</NText><div class="text-xs text-zinc-500">{{report.provider??'Provedor não informado'}} · {{report.model??'modelo não informado'}} · {{fmt(report.createdAt)}}</div></div><NTag type="info">SHA-256 {{report.checksum.slice(0,12)}}…</NTag></div><NAlert class="mt-3" type="default" title="Análise do agente">{{report.summary}}</NAlert><div v-if="report.facts.length" class="mt-3"><strong>Fatos observados</strong><ul class="list-disc pl-5"><li v-for="f in report.facts" :key="f">{{f}}</li></ul></div><NAlert v-if="report.hypotheses.length" type="warning" class="mt-3" title="Hipóteses — exigem validação"><ul class="list-disc pl-5"><li v-for="h in report.hypotheses" :key="h">{{h}}</li></ul></NAlert><div v-if="report.risks.length" class="mt-3"><strong>Riscos</strong><ul class="list-disc pl-5"><li v-for="v in report.risks" :key="v">{{v}}</li></ul></div><div v-if="report.recommendations.length" class="mt-3"><strong>Próximos passos</strong><ul class="list-disc pl-5"><li v-for="v in report.recommendations" :key="v">{{v}}</li></ul></div><div v-if="report.evidence.length" class="mt-3 text-xs text-zinc-400">Evidências: <span v-for="(e,index) in report.evidence" :key="e.actionRunId"><span v-if="index"> · </span>ActionRun #{{e.actionRunId}}<span v-if="e.stepIds.length"> ({{e.stepIds.join(', ')}})</span></span></div><NTag v-if="report.redactionApplied" class="mt-3" type="warning" size="small">Dados sensíveis mascarados</NTag></NCard></div><NEmpty v-else description="A investigação ainda não possui conclusão do agente."/></template></NSpin></div></template>
